class TopologyRouter:
    """Bandwidth router for the three-node physical topology.

    Every route is bounded by the per-switch ``local_capacity`` and the sum of
    all active allocations is bounded by the central backbone
    ``global_capacity``.  When the aggregate demand over-subscribes the
    backbone, every route is scaled down proportionally so the total stays
    within the backbone limit while keeping the load balanced across routes.
    """

    def __init__(self, local_capacity: float = 100.0, global_capacity: float = 150.0):
        self.local_capacity = float(local_capacity)
        self.global_capacity = float(global_capacity)

    def allocate_bandwidth(self, demands: dict[str, float]) -> dict[str, float]:
        """Allocate bandwidth for each route.

        Each route receives at most its demand and at most ``local_capacity``.
        If the sum of those local allocations exceeds ``global_capacity``, all
        allocations are scaled back uniformly so their sum fits the backbone.
        """
        allocations = {}
        for path, demand in demands.items():
            allocations[path] = min(max(0.0, float(demand)), self.local_capacity)

        total = sum(allocations.values())
        if total > self.global_capacity:
            if total > 0 and self.global_capacity > 0:
                scale = self.global_capacity / total
                allocations = {path: value * scale for path, value in allocations.items()}
            else:
                allocations = {path: 0.0 for path in allocations}

        # Guard against floating point drift so the capacity guarantees hold.
        if sum(allocations.values()) > self.global_capacity:
            overflow = sum(allocations.values()) - self.global_capacity
            shrinkable = [p for p, v in allocations.items() if v > 0.0]
            if shrinkable:
                correction = overflow / len(shrinkable)
                for path in shrinkable:
                    allocations[path] = max(0.0, allocations[path] - correction)

        return allocations

