class GlobalBackboneScheduler:
    def __init__(self, local_capacity: float = 100.0, global_capacity: float = 180.0):
        self.local_capacity = local_capacity
        self.global_capacity = global_capacity

    def allocate_bandwidth(self, demands: dict[str, float]) -> dict[str, float]:
        """Allocate bandwidth across the active routes (Node 1 / Node 2 / Node 3 paths).

        Two constraints must hold at all times:

        1. Local switch constraint - a single path may never be allocated more
           than ``local_capacity``. The local allocation logic was already
           correct, so it is preserved here.
        2. Global backbone constraint - every active route crosses the central
           backbone router, so the *sum* of all allocations must not exceed
           ``global_capacity``. Under high traffic demands the allocations are
           scaled down proportionally (each route keeps its fair share of the
           backbone) so the aggregate limit is never overflowed.

        Returns one allocation per demand key; allocations are never negative
        and never exceed the requested demand.
        """
        if not demands:
            return {}

        # Normalise demands: anything that is not a positive number is treated
        # as a request for zero bandwidth.
        normalized: dict[str, float] = {}
        for path, demand in demands.items():
            try:
                value = float(demand)
            except (TypeError, ValueError):
                value = 0.0
            normalized[path] = value if value > 0.0 else 0.0

        # 1) Local constraint: no single path may exceed a local switch's capacity.
        capped = {path: min(value, self.local_capacity) for path, value in normalized.items()}

        total_demand = sum(capped.values())
        if total_demand <= 0.0:
            return {path: 0.0 for path in capped}

        # 2) Global constraint: scale every active route by the same factor so
        #    the aggregate allocation fits inside the backbone router.
        scale = 1.0
        if total_demand > self.global_capacity:
            scale = self.global_capacity / total_demand

        allocations = {path: value * scale for path, value in capped.items()}

        # Floating point safety net: guarantee the invariant holds exactly.
        total = sum(allocations.values())
        if total > self.global_capacity and total > 0.0:
            factor = self.global_capacity / total
            allocations = {path: value * factor for path, value in allocations.items()}

        return allocations

class SheafPathAllocator:
    """Topologically aware bandwidth allocator for a 3-node GPU cluster.

    Traffic between the nodes flows over overlapping routes that share edge
    switches (each route is individually bounded by ``local_capacity``) and
    that all traverse a single central backbone router whose aggregate
    capacity is ``global_capacity``.
    """

    def __init__(self, local_capacity: float = 100.0, global_capacity: float = 180.0):
        self.local_capacity = float(local_capacity)
        self.global_capacity = float(global_capacity)

    def allocate_bandwidth(self, demands: dict[str, float]) -> dict[str, float]:
        # Demands are mapped over the (possibly overlapping) paths between
        # Node 1, Node 2 and Node 3, e.g. "route_A"/"route_B"/"route_C" or
        # "node1_2"/"node2_3"/"node1_3".  Any set of keys is accepted.
        if not demands:
            return {}

        # Step 1: local constraint.
        # Every single route is bounded by the capacity of the switches it
        # traverses, so no route may carry more than ``local_capacity`` (nor
        # more than its own demand).
        capped: dict[str, float] = {}
        for path, demand in demands.items():
            if demand is None:
                continue
            capped[path] = max(0.0, min(float(demand), self.local_capacity))

        if not capped:
            return {}

        # Step 2: global constraint.
        # All active routes are multiplexed onto the central backbone router,
        # so the aggregate allocation must never exceed ``global_capacity``.
        # When the concurrent communication loop over-subscribes the backbone,
        # every path is scaled down uniformly (proportional fair sharing).
        limit = max(0.0, self.global_capacity)
        total = sum(capped.values())

        if total > limit:
            scale = limit / total if total > 0.0 else 0.0
            allocations = {path: value * scale for path, value in capped.items()}
            # Compensate for floating point drift so the reported aggregate
            # never exceeds the backbone limit by even an epsilon.
            drift = sum(allocations.values()) - limit
            if drift > 0.0:
                largest = max(allocations, key=allocations.get)
                allocations[largest] = max(0.0, allocations[largest] - drift)
        else:
            allocations = dict(capped)

        return allocations

class SheafPathAllocator:
    def __init__(self, local_capacity: float = 100.0, global_capacity: float = 150.0):
        self.local_capacity = local_capacity
        self.global_capacity = global_capacity

    def allocate_bandwidth(self, demands: dict[str, float]) -> dict[str, float]:
        # Demands are mapped over overlapping paths (e.g. "route_A", "route_B",
        # "route_C", or the node-to-node edges "node1_2" / "node2_3" / "node1_3").
        # Symmetries and overlapping topologies:
        # - Switch S1 is shared by: route_A + route_C (capacity <= local_capacity)
        # - Switch S2 is shared by: route_A + route_B (capacity <= local_capacity)
        # - Switch S3 is shared by: route_B + route_C (capacity <= local_capacity)
        #
        # Every pair of active routes shares exactly one local switch, so the
        # feasible region is defined by x_i + x_j <= local_capacity for each pair of
        # routes, x_i <= local_capacity for a lone route, and sum(x_i) <=
        # global_capacity for the backbone router.
        #
        # We therefore compute the largest common scaling factor t <= 1 applied to
        # the raw demands such that every constraint stays feasible (proportional
        # fairness): low traffic is served unchanged, while concurrently high
        # demands are scaled down together so no switch or the backbone saturates.
        items = [(path, max(0.0, float(demand))) for path, demand in demands.items()]
        if not items:
            return {}

        total = sum(demand for _, demand in items)
        if total <= 0.0:
            return {path: 0.0 for path, _ in items}

        scale = 1.0
        # Central backbone router: aggregate limit over all active routes.
        scale = min(scale, self.global_capacity / total)
        # A single active route cannot exceed its own local switch capacity.
        for _, demand in items:
            if demand > 0.0:
                scale = min(scale, self.local_capacity / demand)
        # Each shared local switch carries exactly two active routes.
        for i in range(len(items)):
            for j in range(i + 1, len(items)):
                shared = items[i][1] + items[j][1]
                if shared > 0.0:
                    scale = min(scale, self.local_capacity / shared)

        return {path: demand * scale for path, demand in items}

